<template>
  <div class="mobile-forgot-password">
    <!-- Step 1: 邮箱输入 -->
    <div v-if="currentStep === 1" class="form-step">
      <div class="header-section">
        <div class="back-button" @click="clickBackToLogin">
          <mobile-l-img :src="'/static/images/back_arrow_icon.png'" w="20px" h="20px" />
        </div>
        <span class="page-title">{{ $t('resetPassword') }}</span>
      </div>

      <div class="form-content">
        <div class="form-group">
          <label class="form-label">{{ $t('yourEmailAddress') }}</label>
          <div class="input-wrapper">
            <input
              type="email"
              v-model="userEmail"
              :placeholder="$t('emailPlaceholder')"
              class="form-input"
            />
          </div>
        </div>

        <div class="button-section">
          <l-button
            :text="$t('sendVerificationCode')"
            :disabled="!isEmailValid"
            :loading="isLoading"
            @onClick="clickSendVerificationCode"
          />
        </div>
      </div>
    </div>

    <!-- Step 2: 创建新密码和验证码（合并后的步骤） -->
    <div v-if="currentStep === 2" class="form-step">
      <div class="header-section">
        <div class="back-button" @click="clickBackToPrevious">
          <mobile-l-img :src="'/static/images/back_arrow_icon.png'" w="20px" h="20px" />
        </div>
        <span class="page-title">{{ $t('createNewPassword') }}</span>
      </div>

      <div class="form-content">


        <div class="form-group">
          <label class="form-label">{{ $t('newPassword') }}</label>
          <div class="input-wrapper" :class="{ 'error': newPasswordError }">
            <input
              :type="showNewPassword ? 'text' : 'password'"
              v-model="newPassword"
              :placeholder="$t('createNewPasswordPlaceholder')"
              class="form-input"
              @blur="validateNewPassword"
            />
            <div class="password-toggle" @click="toggleShowNewPassword">
              <mobile-l-img 
                v-if="showNewPassword" 
                :src="'/static/images/eye_icon1.png'" 
                w="20px" 
                h="20px" 
              />
              <mobile-l-img 
                v-else 
                :src="'/static/images/eye_icon2.png'" 
                w="20px" 
                h="20px" 
              />
            </div>
          </div>
          <p v-if="newPasswordError" class="error-message">{{ newPasswordError }}</p>
        </div>

        <div class="form-group">
          <label class="form-label">{{ $t('confirmPassword') }}</label>
          <div class="input-wrapper" :class="{ 'error': confirmPasswordError }">
            <input
              :type="showConfirmPassword ? 'text' : 'password'"
              v-model="confirmPassword"
              :placeholder="$t('confirmPasswordPlaceholder')"
              class="form-input"
              @blur="validateConfirmPassword"
            />
            <div class="password-toggle" @click="toggleShowConfirmPassword">
              <mobile-l-img 
                v-if="showConfirmPassword" 
                :src="'/static/images/eye_icon1.png'" 
                w="20px" 
                h="20px" 
              />
              <mobile-l-img 
                v-else 
                :src="'/static/images/eye_icon2.png'" 
                w="20px" 
                h="20px" 
              />
            </div>
          </div>
          <p v-if="confirmPasswordError" class="error-message">{{ confirmPasswordError }}</p>
        </div>

        <div class="form-group">
          <label class="form-label">{{ $t('verificationCode') }}</label>
          <div class="input-wrapper" :class="{ 'error': verificationCodeError }">
            <input
              type="text"
              v-model="verificationCode"
              :placeholder="$t('enterVerificationCodePlaceholder')"
              maxlength="8"
              class="form-input"
              @blur="validateVerificationCode"
            />
          </div>
          <p v-if="verificationCodeError" class="error-message">{{ verificationCodeError }}</p>
        </div>

        <p class="verification-sent">{{ $t('verificationSentTo', { email: userEmail }) }}</p>

        <div class="button-section">
          <l-button
            :text="$t('resetPassword')"
            :disabled="!isAllInputsValid"
            :loading="isLoading"
            @onClick="clickResetPassword"
          />
          <p class="resend-text">
            {{ $t('didntReceiveCode') }}
            <span class="resend-link" @click="clickResendCode" :class="{ 'disabled': isResendDisabled }">
              {{ isResendDisabled ? `${$t('resend')}: ${countdown}s` : $t('resend') }}
            </span>
          </p>
        </div>
      </div>
    </div>

    <!-- Step 3: 密码重置成功 -->
    <div v-if="currentStep === 3" class="form-step success-step">
      <div class="form-content">
        <div class="success-content">
          <p class="success-message">{{ $t('passwordResetSuccessfully') }}</p>
          
          <div class="button-section">
            <l-button
              :text="$t('returnToLogin')"
              @onClick="clickReturnToLogin"
            />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onUnmounted } from 'vue';
import { useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import LButton from '@/components/l-button.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import { ROUTER_PATHS } from '@/router/constants';
import { ApiUser } from '@/api/api-user';
import { showToast } from 'vant';

const router = useRouter();
const { t } = useI18n();

// 步骤管理
const currentStep = ref(1); // 从邮箱输入步骤开始

// 表单数据
const userEmail = ref('');
const verificationCode = ref('');
const newPassword = ref('');
const confirmPassword = ref('');
const showNewPassword = ref(false);
const showConfirmPassword = ref(false);
const isLoading = ref(false);

// 错误信息
const newPasswordError = ref('');
const confirmPasswordError = ref('');
const verificationCodeError = ref('');

// 倒计时相关
const countdown = ref(0);
const isResendDisabled = ref(false);
let countdownTimer = null;

// 计算属性
const isEmailValid = computed(() => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return userEmail.value && emailRegex.test(userEmail.value);
});

const isVerificationCodeValid = computed(() => {
  return verificationCode.value && verificationCode.value.length === 8;
});

const arePasswordsValid = computed(() => {
  return newPassword.value.length >= 6 && newPassword.value.length <= 20
    && confirmPassword.value.length >= 6 && confirmPassword.value.length <= 20
    && newPassword.value === confirmPassword.value
    && !newPasswordError.value && !confirmPasswordError.value;
});

// 所有输入是否有效（用于完整的重置密码按钮验证）
const isAllInputsValid = computed(() => {
  return isVerificationCodeValid.value && arePasswordsValid.value;
});

// 点击事件区域
const clickBackToLogin = () => {
  router.push(ROUTER_PATHS.LOGIN);
};

const clickBackToPrevious = () => {
  if (currentStep.value > 1) {
    currentStep.value--;
  } else {
    clickBackToLogin();
  }
};

// 表单验证方法
const validateNewPassword = () => {
  newPasswordError.value = '';
  
  if (newPassword.value) {
    if (newPassword.value.length < 6) {
      newPasswordError.value = t('passwordMustBeAtLeast');
    } else if (newPassword.value.length > 20) {
      newPasswordError.value = t('passwordTooLongTip');
    }
  }
};

const validateConfirmPassword = () => {
  confirmPasswordError.value = '';
  
  if (confirmPassword.value) {
    if (newPassword.value !== confirmPassword.value) {
      confirmPasswordError.value = t('passwordsDoNotMatch');
    }
  }
};

const validateVerificationCode = () => {
  verificationCodeError.value = '';
  
  if (verificationCode.value && verificationCode.value.length !== 8) {
    verificationCodeError.value = t('invalidVerificationCode');
  }
};

// 开始倒计时
const startCountdown = () => {
  isResendDisabled.value = true;
  countdown.value = 60;

  countdownTimer = setInterval(() => {
    if (countdown.value > 1) {
      countdown.value--;
    } else {
      clearInterval(countdownTimer);
      isResendDisabled.value = false;
    }
  }, 1000);
};

// 通用API调用处理函数
const handleApiCall = async (apiFunction, successMessage, errorMessage, onSuccess = null) => {
  try {
    isLoading.value = true;
    const response = await apiFunction();

    if (response && response.code === 200) {
      const successMsg = response.data?.message || successMessage;
              showToast({ message: successMsg});
      if (onSuccess) {
        await onSuccess(response);
      }
      return true;
    } else {
      const errorMsg = response?.message || errorMessage;
      showToast({ message: errorMsg});
      return false;
    }
  } catch (error) {
    console.error(errorMessage, error);
    showToast({ message: errorMessage });
    return false;
  } finally {
    isLoading.value = false;
  }
};

const clickSendVerificationCode = async () => {
  if (isEmailValid.value) {
    const success = await handleApiCall(
      () => ApiUser.requestResetPassword(userEmail.value),
      'Verification code sent successfully',
      'Failed to send verification code',
      async () => {
        currentStep.value = 2;
        startCountdown();
      }
    );
  }
};

const clickResetPassword = async () => {
  validateVerificationCode();
  validateNewPassword();
  validateConfirmPassword();

  if (isAllInputsValid.value) {
    const success = await handleApiCall(
      () => ApiUser.resetPassword(userEmail.value, verificationCode.value, newPassword.value, confirmPassword.value),
      'Password reset successfully',
      'Failed to reset password',
      async () => {
        currentStep.value = 3;
      }
    );
  }
};

const clickResendCode = async () => {
  if (isResendDisabled.value) return;

  const success = await handleApiCall(
    () => ApiUser.requestResetPassword(userEmail.value),
    'Verification code resent successfully',
    'Failed to resend verification code',
    async () => {
      startCountdown();
    }
  );
};

const toggleShowNewPassword = () => {
  showNewPassword.value = !showNewPassword.value;
};

const toggleShowConfirmPassword = () => {
  showConfirmPassword.value = !showConfirmPassword.value;
};

const clickReturnToLogin = () => {
  router.push(ROUTER_PATHS.LOGIN);
};

// 组件卸载时清除定时器
onUnmounted(() => {
  if (countdownTimer) {
    clearInterval(countdownTimer);
  }
});
</script>

